import java.security.SecureRandom;

public class PasteIdGenerator {

    private static final String ALPHABET = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    private static final int ID_LENGTH = 8;
    private static final int MAX_ATTEMPTS = 5;

    private final SecureRandom random = new SecureRandom();
    private final PasteRepository pasteRepository;

    public PasteIdGenerator(PasteRepository pasteRepository) {
        this.pasteRepository = pasteRepository;
    }

    // Draws a fresh random id and retries on the rare chance it already
    // exists. At 8 characters of base62 this loop almost never runs
    // more than once, see the worked collision math in the doc's Trade-Offs
    // section for exactly how rare.
    public String generate() {
        for (int attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
            String candidate = randomId();
            if (!pasteRepository.exists(candidate)) {
                return candidate;
            }
        }
        throw new IllegalStateException("Could not allocate a unique paste id, id space may need widening");
    }

    private String randomId() {
        StringBuilder sb = new StringBuilder(ID_LENGTH);
        for (int i = 0; i < ID_LENGTH; i++) {
            sb.append(ALPHABET.charAt(random.nextInt(ALPHABET.length())));
        }
        return sb.toString();
    }
}

