import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class ContentAddressableBlobStore {

    private final S3Client s3Client;
    private final BlobRefRepository blobRefRepository;
    private final String bucket;

    public ContentAddressableBlobStore(S3Client s3Client, BlobRefRepository blobRefRepository, String bucket) {
        this.s3Client = s3Client;
        this.blobRefRepository = blobRefRepository;
        this.bucket = bucket;
    }

    // The hash of the body doubles as its key, so writing identical
    // content twice becomes a reference count increment, not a second
    // upload.
    public String store(byte[] body) {
        String contentHash = sha256Hex(body);
        if (blobRefRepository.incrementIfExists(contentHash)) {
            return contentHash;
        }
        String key = "pastes/" + contentHash;
        s3Client.putObject(bucket, key, body);
        blobRefRepository.createWithRefCount(contentHash, key, 1);
        return contentHash;
    }

    public byte[] fetch(String contentHash) {
        return s3Client.getObject(bucket, "pastes/" + contentHash);
    }

    // Called by the reaper. The physical object is only removed once no
    // paste anywhere in the system still references it.
    public void release(String contentHash) {
        int remaining = blobRefRepository.decrementAndGet(contentHash);
        if (remaining <= 0) {
            s3Client.deleteObject(bucket, "pastes/" + contentHash);
            blobRefRepository.delete(contentHash);
        }
    }

    private String sha256Hex(byte[] body) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(body);
            StringBuilder hex = new StringBuilder();
            for (byte b : hash) {
                hex.append(String.format("%02x", b));
            }
            return hex.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }
}

