class ContentAddressableBlobStore:
    def __init__(self, s3_client, blob_ref_repository, bucket):
        self.s3_client = s3_client
        self.blob_ref_repository = blob_ref_repository
        self.bucket = bucket

    def store(self, body: bytes) -> str:
        # Two pastes with identical content share one physical object.
        content_hash = hashlib.sha256(body).hexdigest()
        if self.blob_ref_repository.increment_if_exists(content_hash):
            return content_hash
        key = f"pastes/{content_hash}"
        self.s3_client.put_object(self.bucket, key, body)
        self.blob_ref_repository.create_with_ref_count(content_hash, key, 1)
        return content_hash

    def fetch(self, content_hash: str) -> bytes:
        return self.s3_client.get_object(self.bucket, f"pastes/{content_hash}")

    def release(self, content_hash: str) -> None:
        # Called by the reaper, only removes the object once nothing
        # anywhere in the system still references it.
        remaining = self.blob_ref_repository.decrement_and_get(content_hash)
        if remaining <= 0:
            self.s3_client.delete_object(self.bucket, f"pastes/{content_hash}")
            self.blob_ref_repository.delete(content_hash)

