#include <bits/stdc++.h>
using namespace std;

class S3Client {
public:
    virtual void putObject(const string& bucket, const string& key, const string& body) = 0;
    virtual string getObject(const string& bucket, const string& key) = 0;
    virtual void deleteObject(const string& bucket, const string& key) = 0;
    virtual ~S3Client() = default;
};

class BlobRefRepository {
public:
    virtual bool incrementIfExists(const string& contentHash) = 0;
    virtual void createWithRefCount(const string& contentHash, const string& key, int refCount) = 0;
    virtual int decrementAndGet(const string& contentHash) = 0;
    virtual void remove(const string& contentHash) = 0;
    virtual ~BlobRefRepository() = default;
};

class ContentAddressableBlobStore {
    S3Client* s3Client;
    BlobRefRepository* blobRefRepository;
    string bucket;

public:
    ContentAddressableBlobStore(S3Client* s3, BlobRefRepository* refs, string bucketName)
        : s3Client(s3), blobRefRepository(refs), bucket(move(bucketName)) {}

    // Two pastes with identical content share one physical object, the
    // hash of the body doubles as its key.
    string store(const string& body) {
        string contentHash = sha256Hex(body);
        if (blobRefRepository->incrementIfExists(contentHash)) {
            return contentHash;
        }
        string key = "pastes/" + contentHash;
        s3Client->putObject(bucket, key, body);
        blobRefRepository->createWithRefCount(contentHash, key, 1);
        return contentHash;
    }

    string fetch(const string& contentHash) {
        return s3Client->getObject(bucket, "pastes/" + contentHash);
    }

    // Called by the reaper, only removes the object once nothing else
    // in the system still references it.
    void release(const string& contentHash) {
        int remaining = blobRefRepository->decrementAndGet(contentHash);
        if (remaining <= 0) {
            s3Client->deleteObject(bucket, "pastes/" + contentHash);
            blobRefRepository->remove(contentHash);
        }
    }

private:
    // A placeholder hash so this snippet stays dependency free. A real
    // deployment would swap this for a proper SHA-256 implementation,
    // for example via a crypto library like OpenSSL.
    string sha256Hex(const string& body) {
        size_t h = hash<string>{}(body);
        ostringstream oss;
        oss << hex << h;
        return oss.str();
    }
};

