import java.time.Instant;

public class PasteMetadataService {

    private final PasteIdGenerator idGenerator;
    private final ContentAddressableBlobStore blobStore;
    private final PasteRepository pasteRepository;
    private final ScanQueuePublisher scanQueuePublisher;

    public PasteMetadataService(PasteIdGenerator idGenerator, ContentAddressableBlobStore blobStore,
                                 PasteRepository pasteRepository, ScanQueuePublisher scanQueuePublisher) {
        this.idGenerator = idGenerator;
        this.blobStore = blobStore;
        this.pasteRepository = pasteRepository;
        this.scanQueuePublisher = scanQueuePublisher;
    }

    public Paste create(CreatePasteRequest request) {
        // Store the body first. If the metadata write below fails, the
        // orphaned blob is harmless and expires on its own lifecycle rule,
        // whereas the opposite order could leave a metadata row pointing
        // at content that was never actually saved.
        String contentHash = blobStore.store(request.getBody());

        Paste paste = new Paste(
            idGenerator.generate(),
            request.getOwnerId(),
            request.getVisibility(),
            request.getLanguageHint(),
            contentHash,
            request.getBody().length,
            Instant.now(),
            request.getExpiresAt(),
            request.isBurnAfterRead()
        );

        pasteRepository.save(paste);
        // Scanning happens off the hot path, a flagged paste gets pulled
        // down after the fact rather than blocking every legitimate create.
        scanQueuePublisher.publish(paste.getPasteId());
        return paste;
    }
}

