#include <bits/stdc++.h>
using namespace std;

struct CreatePasteRequest {
    string body;
    string ownerId;
    string visibility;
    string languageHint;
    optional<chrono::system_clock::time_point> expiresAt;
    bool burnAfterRead;
};

struct Paste {
    string pasteId;
    string ownerId;
    string visibility;
    string languageHint;
    string contentHash;
    size_t sizeBytes;
    chrono::system_clock::time_point createdAt;
    optional<chrono::system_clock::time_point> expiresAt;
    bool burnAfterRead;
};

class PasteIdGenerator { public: virtual string generate() = 0; virtual ~PasteIdGenerator() = default; };
class ContentAddressableBlobStore { public: virtual string store(const string& body) = 0; virtual ~ContentAddressableBlobStore() = default; };
class PasteRepository { public: virtual void save(const Paste& paste) = 0; virtual ~PasteRepository() = default; };
class ScanQueuePublisher { public: virtual void publish(const string& pasteId) = 0; virtual ~ScanQueuePublisher() = default; };

class PasteMetadataService {
    PasteIdGenerator* idGenerator;
    ContentAddressableBlobStore* blobStore;
    PasteRepository* pasteRepository;
    ScanQueuePublisher* scanQueuePublisher;

public:
    PasteMetadataService(PasteIdGenerator* idGen, ContentAddressableBlobStore* blobs,
                          PasteRepository* repo, ScanQueuePublisher* scanner)
        : idGenerator(idGen), blobStore(blobs), pasteRepository(repo), scanQueuePublisher(scanner) {}

    Paste create(const CreatePasteRequest& request) {
        // Store the body first, an orphaned blob on a later failure is
        // harmless, an orphaned metadata row pointing at nothing is not.
        string contentHash = blobStore->store(request.body);

        Paste paste{
            idGenerator->generate(), request.ownerId, request.visibility, request.languageHint,
            contentHash, request.body.size(), chrono::system_clock::now(),
