#include <bits/stdc++.h>
using namespace std;

struct Paste {
    string pasteId;
    string ownerId;
    string visibility;
    string contentHash;
    optional<chrono::system_clock::time_point> expiresAt;
    bool burnAfterRead;
};

struct PasteView {
    Paste paste;
    string body;
};

class PasteNotFoundException : public runtime_error {
public:
    explicit PasteNotFoundException(const string& pasteId) : runtime_error("paste not found: " + pasteId) {}
};

class CacheClient {
public:
    virtual optional<PasteView> get(const string& pasteId) = 0;
    virtual void put(const string& pasteId, const PasteView& view, optional<chrono::system_clock::time_point> expiresAt) = 0;
    virtual void evict(const string& pasteId) = 0;
    virtual ~CacheClient() = default;
};

class PasteRepository {
public:
    virtual optional<Paste> findById(const string& pasteId) = 0;
    virtual void markExpiredImmediately(const string& pasteId) = 0;
    virtual ~PasteRepository() = default;
};

class BlobStore {
public:
    virtual string fetch(const string& contentHash) = 0;
    virtual ~BlobStore() = default;
};

class PasteReadService {
    CacheClient* cache;
    PasteRepository* pasteRepository;
    BlobStore* blobStore;

public:
    PasteReadService(CacheClient* c, PasteRepository* repo, BlobStore* blobs)
        : cache(c), pasteRepository(repo), blobStore(blobs) {}

    PasteView read(const string& pasteId, const optional<string>& requestingUserId) {
        auto cached = cache->get(pasteId);
        if (cached.has_value()) {
            return finishRead(cached.value(), requestingUserId);
        }

        auto pasteOpt = pasteRepository->findById(pasteId);
        bool expired = pasteOpt.has_value() && pasteOpt->expiresAt.has_value()
            && pasteOpt->expiresAt.value() < chrono::system_clock::now();
        if (!pasteOpt.has_value() || expired) {
            // Not-yet-reaped but expired rows are treated as missing.
            throw PasteNotFoundException(pasteId);
        }

        string body = blobStore->fetch(pasteOpt->contentHash);
        PasteView view{pasteOpt.value(), body};

        // Immutable content never needs invalidation, only an expiry
        // aligned to the paste's own TTL.
        cache->put(pasteId, view, pasteOpt->expiresAt);
        return finishRead(view, requestingUserId);
    }

private:
    PasteView finishRead(PasteView view, const optional<string>& requestingUserId) {
        enforceVisibility(view.paste, requestingUserId);
        if (view.paste.burnAfterRead) {
            pasteRepository->markExpiredImmediately(view.paste.pasteId);
            cache->evict(view.paste.pasteId);
        }
        return view;
    }

    void enforceVisibility(const Paste& paste, const optional<string>& requestingUserId) {
        bool isPrivate = paste.visibility == "PRIVATE";
        bool isOwner = requestingUserId.has_value() && requestingUserId.value() == paste.ownerId;
        if (isPrivate && !isOwner) {
            // Same error as a missing id, existence is never leaked.
            throw PasteNotFoundException(paste.pasteId);
        }
    }
};

