import java.time.Instant;
import java.util.List;

public class PasteExpirationReaper {

    private static final int BATCH_SIZE = 500;

    private final PasteRepository pasteRepository;
    private final ContentAddressableBlobStore blobStore;
    private final CacheClient cache;

    public PasteExpirationReaper(PasteRepository pasteRepository, ContentAddressableBlobStore blobStore, CacheClient cache) {
        this.pasteRepository = pasteRepository;
        this.blobStore = blobStore;
        this.cache = cache;
    }

    // Runs on a schedule (every minute is plenty). Deletes in small
    // batches so a slow sweep never holds a long-lived lock or scan
    // against the metadata table.
    public void sweep() {
        List<Paste> expired = pasteRepository.findExpiredBatch(Instant.now(), BATCH_SIZE);
        for (Paste paste : expired) {
            // Only drops the physical object once its reference count
            // hits zero, so a duplicate-content paste created by someone
            // else is never affected by this paste's own expiry.
            blobStore.release(paste.getContentHash());
            pasteRepository.delete(paste.getPasteId());
            cache.evict(paste.getPasteId());
        }
    }
}

