import java.time.Duration;
import java.time.Instant;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class PasteRateLimiter {

    private static final int MAX_TOKENS = 20;
    private static final double REFILL_PER_SECOND = 0.5; // one new paste every 2 seconds, sustained

    private final Map<String, Bucket> buckets = new ConcurrentHashMap<>();

    // Called once per create request, keyed by user id or IP for
    // anonymous callers. Returns false when the caller should get a 429.
    public boolean tryAcquire(String key) {
        Bucket bucket = buckets.computeIfAbsent(key, k -> new Bucket(MAX_TOKENS, Instant.now()));
        synchronized (bucket) {
            refill(bucket);
            if (bucket.tokens >= 1.0) {
                bucket.tokens -= 1.0;
                return true;
            }
            return false;
        }
    }

    private void refill(Bucket bucket) {
        Instant now = Instant.now();
        double elapsedSeconds = Duration.between(bucket.lastRefill, now).toMillis() / 1000.0;
        bucket.tokens = Math.min(MAX_TOKENS, bucket.tokens + elapsedSeconds * REFILL_PER_SECOND);
        bucket.lastRefill = now;
    }

    private static class Bucket {
        double tokens;
        Instant lastRefill;

        Bucket(double tokens, Instant lastRefill) {
            this.tokens = tokens;
            this.lastRefill = lastRefill;
        }
    }
}

