constexpr double MAX_TOKENS = 20.0;
constexpr double REFILL_PER_SECOND = 0.5; // one new paste every 2 seconds, sustained

struct Bucket {
    double tokens;
    chrono::steady_clock::time_point lastRefill;
    mutex bucketMutex;
};

class PasteRateLimiter {
    unordered_map<string, unique_ptr<Bucket>> buckets;
    mutex bucketsMutex;

public:
    // Called once per create request, keyed by user id or IP for
    // anonymous callers. Returns false when the caller should get a 429.
    bool tryAcquire(const string& key) {
        Bucket* bucket;
        {
            lock_guard<mutex> lock(bucketsMutex);
            auto it = buckets.find(key);
            if (it == buckets.end()) {
                auto newBucket = make_unique<Bucket>();
                newBucket->tokens = MAX_TOKENS;
                newBucket->lastRefill = chrono::steady_clock::now();
                bucket = newBucket.get();
                buckets.emplace(key, move(newBucket));
            } else {
                bucket = it->second.get();
            }
        }

        lock_guard<mutex> lock(bucket->bucketMutex);
        refill(*bucket);
        if (bucket->tokens >= 1.0) {
            bucket->tokens -= 1.0;
            return true;
        }
        return false;
    }

private:
    void refill(Bucket& bucket) {
        auto now = chrono::steady_clock::now();
        double elapsedSeconds = chrono::duration<double>(now - bucket.lastRefill).count();
        bucket.tokens = min(MAX_TOKENS, bucket.tokens + elapsedSeconds * REFILL_PER_SECOND);
        bucket.lastRefill = now;
    }
};

